/* Campaign encounter controller; the workshop remains a separate non-rewarding sandbox. */
(function(){
'use strict';
const C=DecideCombatRules,D=EverTaleBattleData;
const panel=document.createElement('article');panel.className='expedition-entry';panel.innerHTML='<div><p class="eyebrow">TACTICAL EXPEDITION</p><h2>ออกผจญภัย</h2><p>ใช้ตัวละครของคุณต่อสู้ในสนาม • 2 ชั่วโมง / พลังงาน 15 • แพ้กลับมาที่ 15 HP</p></div><label>เลือกสนาม<select id="expeditionScene"></select></label><button id="expeditionStart" class="primary">⚔ เข้าสนาม</button><p id="expeditionHint" role="status"></p>';$('gameScreen').prepend(panel);
const section=document.createElement('section');section.id='combatScreen';section.hidden=true;section.innerHTML=`<div class="combat-heading"><div><p class="eyebrow">DECIDE FATE · EXPEDITION</p><h1 id="combatTitle"></h1><p id="combatTurn" aria-live="polite"></p></div><button id="combatRetreat">ถอนตัว</button></div><div class="combat-layout"><div><div class="combat-toolbar"><button id="combatZoomOut" aria-label="ซูมออก">−</button><button id="combatZoomIn" aria-label="ซูมเข้า">＋</button><button id="combatFit">พอดีจอ</button><label><input id="combatGhost" type="checkbox"> มองทะลุต้นไม้</label></div><canvas id="combatCanvas" tabindex="0" aria-label="สนามต่อสู้ ใช้ลูกศรเลือกช่อง Enter เลือกเป้าหมาย"></canvas><p id="combatTarget" role="status"></p><div class="combat-actions"><button id="combatMove">เดิน</button><button id="combatClimb">ปีน / ลง</button><button id="combatAttack" class="primary">โจมตี</button><button id="combatSkill">สกิล</button><button id="combatGuard">ตั้งรับ</button><button id="combatPotion">ใช้ยา</button><button id="combatInteract">ใช้วัตถุ</button><button id="combatEnd" class="primary">จบเทิร์น →</button></div><p id="combatNotice" role="status" aria-live="polite"></p><article id="combatResult" hidden><h2 id="combatResultTitle"></h2><p id="combatReward"></p><button id="combatReturn" class="primary">รับผลและกลับแผนที่</button></article></div><aside><div id="combatHero"></div><div id="combatEnemies"></div><details open><summary>บันทึกการต่อสู้</summary><ol id="combatLog"></ol></details><details><summary>วิธีเล่น</summary><p>แตะช่องแล้วกดเดิน ใช้ได้ 6 แต้มต่อเทิร์น โจมตี สกิล ตั้งรับ ใช้ยา หรือใช้วัตถุ เลือกทำได้ 1 อย่างต่อเทิร์น จากนั้นกดจบเทิร์นให้ศัตรูเดินและตอบโต้</p><p>สกิลใช้มานา 8 หน่วย นักบวชและนักปรุงยาฟื้นสุขภาพตัวเอง อาชีพอื่นโจมตีแรงขึ้น ระยะและความเสียหายขึ้นกับอาชีพกับค่าสถานะ • กติกาสกิลฉบับทดสอบ</p><p>ยาฟื้นฟู 2 ขวดต่อสนาม หีบ แร่ และสมุนไพรใช้ได้ครั้งเดียวต่อสนาม รับเหรียญเมื่อชนะเท่านั้น การต่อสู้บันทึกทุกแอ็กชัน สามารถรีเฟรชแล้วกดเล่นต่อได้</p></details></aside></div>`;$('menuScreen').parentNode.insertBefore(section,$('globalStatus'));
const canvas=$('combatCanvas'),view=EverTaleBattleView.create(canvas);let selected=0,targetId=null,drag=null,notice='';
const encounter=()=>s.expedition;
function scenes(){const config=DB.overrides?.[D.KEY]||D.defaults();return config.scenes.filter(x=>!D.inspect(x).issues.length);}
function entry(){const select=$('expeditionScene'),prior=select.value;select.replaceChildren();for(const scene of scenes())select.add(new Option(D.biomes[scene.biome]+' / '+scene.name,scene.id));if([...select.options].some(x=>x.value===prior))select.value=prior;select.disabled=!!s.expedition;$('expeditionStart').textContent=s.expedition?'⚔ เล่นการต่อสู้ต่อ':'⚔ เข้าสนาม';$('expeditionStart').disabled=!s.character||s.dead||!!s.event||(!s.expedition&&(s.hp<20||s.energy<15||!select.options.length));$('expeditionHint').textContent=s.expedition?'มีสนามที่บันทึกไว้ • เล่นต่อเพื่อรับผลก่อนทำกิจกรรมอื่น':!select.options.length?'ยังไม่มีฉากที่มีจุดเกิดและทางเดินครบ • สร้างหรือแก้ฉากก่อน':s.hp<20||s.energy<15?'พักฟื้นก่อนเข้าสนาม':'';}
function launch(preferredBiome){try{if(!s.expedition){const available=scenes(),scene=(preferredBiome?available.find(x=>x.biome===preferredBiome):available.find(x=>x.id===$('expeditionScene').value))||available[0];if(!scene)throw Error('ยังไม่มีฉากที่พร้อมต่อสู้');const e=C.create(scene,s,R.records(DB).filter(x=>x.kind==='monster'),crypto.randomUUID());R.clock(s,120);s.turn++;s.energy-=15;s.expedition=e;R.log(s,'ออกผจญภัยที่ '+scene.name+' • พลังงาน −15');save();}selected=D.index(s.expedition.units[0].n);targetId=null;notice='เลือกช่องเพื่อเดิน หรือเลือกศัตรูเพื่อโจมตี';show('combatScreen');draw();view.fit(s.expedition.scene);}catch(error){$('expeditionHint').textContent=error.message;status(error.message);}}
function draw(){const e=encounter();if(!e||screen!=='combatScreen')return;const p=e.units[0],enemy=e.units.find(u=>u.id===targetId&&u.hp>0),route=C.path(e,D.node(selected)),cost=route.reduce((n,x)=>n+x.cost,0),active=e.status==='active';
 $('combatTitle').textContent=e.scene.name;$('combatTurn').textContent='เทิร์น '+e.round+' • เดิน '+p.move+'/6 • แอ็กชัน '+p.action+'/1';
 $('combatHero').replaceChildren();const title=document.createElement('h2');title.textContent=p.name+' · '+R.classes.find(j=>j[0]===p.job)[1];const stats=document.createElement('p');stats.textContent='HP '+p.hp+'/'+p.maxHp+' · มานา '+p.mana+'/'+p.maxMana+' · ระยะ '+p.range;const bar=document.createElement('progress');bar.max=p.maxHp;bar.value=p.hp;bar.setAttribute('aria-label','สุขภาพผู้เล่น');$('combatHero').append(title,stats,bar);
 $('combatEnemies').replaceChildren();for(const u of e.units.slice(1)){const b=document.createElement('button');b.type='button';b.className='combat-enemy'+(targetId===u.id?' selected':'');b.disabled=!active||u.hp===0;b.textContent=u.name+' · HP '+u.hp+'/'+u.maxHp+(u.hp===0?' • พ่ายแพ้':'');b.onclick=()=>{targetId=u.id;selected=D.index(u.n);draw();};$('combatEnemies').append(b);}
 $('combatTarget').textContent=enemy?'เป้าหมาย: '+enemy.name+(C.canHit(e,p,enemy)?' • อยู่ในระยะโจมตี':' • อยู่นอกระยะหรือมีสิ่งบัง'):'ช่อง '+(selected%e.scene.w+1)+', '+(Math.floor(selected/e.scene.w)+1)+' · '+D.objects[e.scene.cells[selected].object]+(route.length?' • เดิน '+cost+' แต้ม':'');
 $('combatMove').disabled=!active||!route.length||cost>p.move;$('combatAttack').disabled=!active||!p.action||!enemy||!C.canHit(e,p,enemy);
 $('combatClimb').disabled=!active||e.scene.cells[D.index(p.n)].object!=='tree'||!e.scene.cells[D.index(p.n)].climb||p.move<3;
 const heal=['priest','alchemist'].includes(p.job);$('combatSkill').textContent=C.jobs[p.job][0]+' · 8 มานา';$('combatSkill').disabled=!active||!p.action||p.mana<8||(heal?p.hp===p.maxHp:!enemy||!C.canHit(e,p,enemy));
 $('combatGuard').disabled=!active||!p.action;$('combatPotion').textContent='ยา +35 HP · '+e.potions;$('combatPotion').disabled=!active||!p.action||!e.potions||p.hp===p.maxHp;
 $('combatInteract').disabled=!active||!p.action||e.used.includes(selected)||C.distance(e.scene,p.n,D.node(selected))>1||!['chest','tent','campfire','mushroom','redMushroom','flowers','goldOre','rubyOre','crystal'].includes(e.scene.cells[selected].object);
 $('combatEnd').disabled=$('combatRetreat').disabled=!active;$('combatNotice').textContent=notice;
 $('combatResult').hidden=active;if(!active){const r=C.reward(e);$('combatResultTitle').textContent={won:'ชนะการต่อสู้',lost:'พ่ายแพ้ • กลับมาพักฟื้น',retreated:'ถอนตัวจากสนาม'}[e.status];$('combatReward').textContent='รางวัล '+r.gold+' เหรียญ / '+r.xp+' EXP'+(e.status==='lost'?' • กลับมาที่ 15 HP':'');}
 $('combatLog').replaceChildren();for(const text of e.log){const li=document.createElement('li');li.textContent=text;$('combatLog').append(li);}
 const units=e.units.filter(u=>u.hp>0).map((u,i)=>({...u,mp:u.move,number:i+1}));view.draw(e.scene,{selected,testing:true,units,active:units.findIndex(u=>u.id==='hero'),route:enemy?[]:route,grid:true,ghost:$('combatGhost').checked});
}
function action(fn){try{if(!encounter())return;fn(encounter());notice='';save();draw();}catch(error){notice=error.message;draw();}}
$('expeditionStart').onclick=()=>launch();$('combatMove').onclick=()=>action(e=>C.move(e,D.node(selected)));$('combatClimb').onclick=()=>action(e=>C.move(e,e.units[0].n^1));$('combatAttack').onclick=()=>action(e=>C.attack(e,targetId));$('combatSkill').onclick=()=>action(e=>C.attack(e,targetId,true));$('combatGuard').onclick=()=>action(C.guard);$('combatPotion').onclick=()=>action(C.potion);$('combatInteract').onclick=()=>action(e=>C.interact(e,selected));$('combatEnd').onclick=()=>action(C.endTurn);
$('combatRetreat').onclick=()=>{if(confirm('ถอนตัวจากสนาม? จะไม่ได้รับเหรียญหรือ EXP และสุขภาพที่เสียไปยังคงอยู่'))action(C.retreat);};
$('combatReturn').onclick=()=>{try{const result=C.settle(s);s=result.snapshot;R.log(s,(result.status==='won'?'ชนะการต่อสู้':result.status==='lost'?'พ่ายแพ้และกลับพักฟื้น':'ถอนตัว')+' • +'+result.reward.gold+' เหรียญ / +'+result.reward.xp+' EXP');save();show('gameScreen');}catch(error){notice=error.message;draw();}};
function select(x,y){const i=view.pick(encounter().scene,x,y);if(i===null)return;selected=i;targetId=encounter().units.find(u=>u.side==='enemy'&&u.hp>0&&D.index(u.n)===i)?.id||null;draw();}
canvas.onpointerdown=e=>{if(!encounter())return;const r=canvas.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});};
canvas.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6)drag.moved=true;if(drag.moved)view.pan(e.clientX-drag.lastX,e.clientY-drag.lastY);drag.lastX=e.clientX;drag.lastY=e.clientY;};
canvas.onpointerup=e=>{if(!drag)return;const r=canvas.getBoundingClientRect();if(!drag.moved)select(e.clientX-r.left,e.clientY-r.top);drag=null;};canvas.onpointercancel=()=>drag=null;
canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();view.zoom(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top);},{passive:false});
canvas.onkeydown=e=>{if(!encounter())return;const scene=encounter().scene,x=selected%scene.w,y=Math.floor(selected/scene.w);if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft'&&x>0)selected--;if(e.key==='ArrowRight'&&x<scene.w-1)selected++;if(e.key==='ArrowUp'&&y>0)selected-=scene.w;if(e.key==='ArrowDown'&&y<scene.h-1)selected+=scene.w;targetId=encounter().units.find(u=>u.side==='enemy'&&u.hp>0&&D.index(u.n)===selected)?.id||null;draw();}};
$('combatFit').onclick=()=>encounter()&&view.fit(encounter().scene);$('combatZoomIn').onclick=()=>view.zoom(1.2);$('combatZoomOut').onclick=()=>view.zoom(1/1.2);$('combatGhost').onchange=draw;new ResizeObserver(()=>{if(screen==='combatScreen')draw();}).observe(canvas);
window.EverTaleCombat={launch,entry,draw,reset(){selected=0;targetId=null;drag=null;notice='';},cellPoint(x,y){return view.cellPoint(encounter().scene,y*encounter().scene.w+x);}};
})();
